"""Curious kids (6–10) unique why-scripts. English only."""

from __future__ import annotations

# title, scene, accent, 4 narration lines
KIDS: list[tuple] = [
    ("Why Do We Sneeze?", "sneeze", "#4FC3F7", "Your nose just launched a tiny hurricane.", "A sneeze pushes out dust or pollen that does not belong.", "That air can race faster than a car.", "Cover with your elbow. Your body is helping you."),
    ("Why Is the Sky Blue?", "sky", "#2196F3", "The sky is not painted blue.", "Sunlight is many colors mixed together.", "Air scatters blue light the most, so blue fills the sky.", "At sunset the light travels farther and looks warmer."),
    ("Why Does It Rain?", "rain", "#29B6F6", "Rain is not the sky crying.", "Warm air lifts tiny water drops.", "They join into heavier drops and fall.", "That fall is rain, and it waters the ground."),
    ("Why Is There Thunder?", "cloud", "#546E7A", "Thunder is a sound, not a monster.", "Lightning heats air so fast the air jumps.", "That jump makes a boom we call thunder.", "If you hear thunder, go inside and stay safe."),
    ("Why Do Rainbows Appear?", "rainbow", "#EC407A", "A rainbow is sunlight playing in rain.", "Drops bend light and split it into colors.", "Red on top. Violet below.", "You need sun at your back and rain in front."),
    ("Why Do We See Shadows?", "shadow", "#78909C", "A shadow is a light-blocker shape.", "Your body stops some light from hitting the ground.", "Move, and the shadow moves.", "No light, no shadow."),
    ("Why Do Magnets Stick?", "magnet", "#E53935", "A magnet pulls some metals.", "Iron and steel feel that invisible pull.", "North and south poles can snap together.", "Two same poles push apart."),
    ("Why Do Ice Cubes Melt?", "ice", "#81D4FA", "Ice is water that got very cold.", "Heat gives the bits of water more wiggle.", "They slip out of the ice shape.", "That is melting. Now it is water again."),
    ("Why Do Boats Float?", "wave", "#26C6DA", "A boat is heavy, yet it floats.", "It pushes water out of the way.", "The water pushes back.", "If the push-back wins, the boat stays up."),
    ("Why Do We Yawn?", "heart", "#90CAF9", "A yawn is a big slow breath.", "Your body may want extra air or a stretch.", "Yawns can spread when you see one.", "It is a sleepy signal, not a scare."),
    ("Why Do We Hiccup?", "heart", "#80CBC4", "A hiccup is a tiny jump in your breathing muscle.", "Air pops through and makes a hic sound.", "Most hiccups stop on their own.", "Sip water slowly if they hang around."),
    ("Why Do We Blink?", "eye", "#90CAF9", "Blink. Your eyes just washed themselves.", "Tears are a thin clean film.", "Blinking spreads that film like a tiny wiper.", "That is why eyes do not dry out."),
    ("Why Do We Have Belly Buttons?", "heart", "#FFAB91", "Your belly button is an old door.", "Before you were born, a cord brought food and oxygen.", "After birth the cord is not needed.", "The little mark is where it used to be."),
    ("Why Do Teeth Fall Out?", "tooth", "#FFF8E1", "Baby teeth are starters, not forever teeth.", "Grown-up teeth need more space.", "The baby tooth gets wobbly and comes out.", "A bigger tooth is waiting underneath."),
    ("Why Do We Need Sleep?", "moon", "#5C6BC0", "Sleep is not wasted time.", "Your brain files memories while you rest.", "Your body repairs little wear and tear.", "That is why sleep helps you learn tomorrow."),
    ("Why Does Soap Clean Hands?", "wash", "#4DB6AC", "Soap loves grease and water at once.", "It surrounds tiny bits of dirt.", "Water then rinses those bits away.", "Twenty seconds of rubbing does the job."),
    ("Why Do Onions Make Us Cry?", "apple", "#FFCC80", "An onion makes a sharp gas when you cut it.", "That gas tickles your eyes.", "Tears wash the tickle out.", "It is not sadness. It is chemistry."),
    ("Why Is Fire Hot?", "fire", "#FF7043", "Fire is a fast chemical change.", "Fuel plus oxygen plus heat keep it going.", "The change releases extra heat and light.", "Never touch fire. Grown-ups handle it."),
    ("Why Do Leaves Change Color?", "leaf", "#FFA726", "Green leaves hide other colors in summer.", "In fall, the green fades.", "Yellow and orange were there all along.", "The tree is getting ready to rest."),
    ("Why Do Bees Make Honey?", "bee", "#FBC02D", "Bees gather sweet nectar from flowers.", "They dry it in the hive.", "That becomes honey, a winter food store.", "We can share a little. Thank the bees."),
    ("Why Do Birds Migrate?", "bird", "#26A69A", "Some birds fly far when seasons change.", "They follow food and safer weather.", "The trip can be thousands of kilometers.", "They navigate with sun, stars, and Earth's pull."),
    ("Why Do Fish Have Gills?", "fish", "#26C6DA", "Fish do not breathe like we do.", "Gills pull oxygen out of water.", "Water in. Oxygen stay. Water out.", "That is a fish's quiet breathing."),
    ("Why Is the Ocean Salty?", "wave", "#0277BD", "Rivers carry tiny bits of rock to the sea.", "Those bits include salt.", "The sun lifts fresh water as vapor.", "Salt stays behind, so the ocean tastes salty."),
    ("Why Do We Have Seasons?", "earth", "#66BB6A", "Earth is tilted as it goes around the sun.", "Your half leans toward the sun in summer.", "It leans away in winter.", "That tilt is why seasons change."),
    ("Why Does the Moon Change Shape?", "moon", "#FFE082", "The moon does not really shrink.", "Sunlight hits different parts as it travels.", "We see a sliver, a half, then a full coin.", "Those looks are called phases."),
    ("Why Do Stars Twinkle?", "star", "#FFD54F", "Stars are steady. Air is not.", "Our air jiggles the starlight.", "That jiggle looks like a twinkle.", "In space, stars shine still."),
    ("Why Is Space Silent?", "rocket", "#1A237E", "Sound needs something to shake, like air.", "Space is almost empty.", "No air, no sound wave.", "Astronauts talk by radio instead."),
    ("Why Do We Hear Echoes?", "ear", "#FFCCBC", "A shout is a sound wave.", "A hard wall can bounce it back.", "If the bounce takes long enough, you hear it again.", "That second hello is an echo."),
    ("Why Do Balloons Stick to Hair?", "bubble", "#EF9A9A", "Rub a balloon. Charges move.", "The balloon and hair pull toward each other.", "That is static electricity, not magic.", "Then the charges slowly sneak away."),
    ("Why Does Bread Rise?", "apple", "#D7CCC8", "Yeast is a tiny living helper.", "It eats sugar and makes bubbles of gas.", "Those bubbles puff the dough.", "Bake it, and the puff stays as soft bread."),
    ("Why Do Apples Turn Brown?", "apple", "#E53935", "Cut an apple and air touches it.", "A natural chemical starts a slow change.", "The cut goes brown.", "Lemon juice can slow that change."),
    ("Why Do We Get Goosebumps?", "heart", "#BCAAA4", "Tiny muscles at hair roots squeeze.", "Hairs stand up. Skin looks bumpy.", "Long ago that helped trap warmth.", "Now it is a leftover trick when you feel chilly or amazed."),
    ("Why Do We Sweat?", "water", "#80DEEA", "Sweat is your body's cooling spray.", "When it dries, it takes heat with it.", "That is evaporation at work.", "Drink water when you sweat a lot."),
    ("Why Does Metal Feel Cold?", "rock", "#90A4AE", "Metal is not always colder than wood.", "It just steals heat from your fingers fast.", "Your skin feels that theft as cold.", "Wood steals heat slowly, so it feels warmer."),
    ("Why Do We See Lightning First?", "cloud", "#FFD54F", "Light is much faster than sound.", "The flash reaches you almost instantly.", "The boom lags behind.", "Count the seconds. More seconds means farther lightning."),
    ("Why Do Penguins Huddle?", "animal", "#455A64", "Antarctica is bitterly cold.", "Penguins pack together to share warmth.", "They take turns on the chilly outside.", "Teamwork is their winter coat."),
    ("Why Do Whales Sing?", "whale", "#0277BD", "Some whales make long patterned sounds.", "Those songs can travel far underwater.", "They help whales find each other.", "It is talking, in whale style."),
    ("Why Do Elephants Have Trunks?", "animal", "#BCAAA4", "A trunk is a nose plus a tool.", "It smells, drinks, and picks up food.", "It can be gentle or strong.", "One trunk, many jobs."),
    ("Why Do Camels Have Humps?", "animal", "#D7CCC8", "A hump is not a water tank.", "It stores fat for long dry trips.", "The camel uses that energy when food is scarce.", "That is desert cleverness."),
    ("Why Do Bats Sleep Upside Down?", "animal", "#5D4037", "Bat legs are built to hang, not to stand long.", "Hanging lets them drop into flight fast.", "Caves and trees make good hangars.", "Upside down is right-side up for a bat."),
    ("Why Do Owls Fly Quietly?", "bird", "#6D4C41", "Owl wing feathers have soft edges.", "Air whispers instead of whooshes.", "Prey does not hear them coming.", "Quiet wings are a night hunter's trick."),
    ("Why Do Spiders Make Silk?", "ant", "#8D6E63", "Spider silk is a super-strong thread they make.", "Webs catch food. Lines help them travel.", "It is not Halloween. It is engineering.", "Give spiders space. They help eat bugs."),
    ("Why Do Frogs Start as Tadpoles?", "frog", "#9CCC65", "A tadpole lives in water and has a tail.", "Legs grow. Lungs get ready.", "The tail shrinks. A frog hops onto land.", "That change is called metamorphosis."),
    ("Why Do Butterflies Have Wings?", "seed", "#CE93D8", "Wings let a butterfly travel to flowers.", "Scales on the wings make the colors.", "Nectar is the fuel.", "A flying flower-visitor helps plants too."),
    ("Why Do Trees Have Bark?", "tree", "#6D4C41", "Bark is a tree's jacket.", "It keeps bugs and weather off the living wood.", "New bark grows as the tree thickens.", "Do not peel bark. The tree needs it."),
    ("Why Do Flowers Smell?", "seed", "#F48FB1", "Scent is a flower's advertisement.", "Bees and other visitors follow the smell.", "They pick up pollen and move it.", "The smell helps the plant make seeds."),
    ("Why Do Seeds Travel?", "seed", "#A5D6A7", "If every seed fell under the parent, they would crowd.", "Wind, water, fur, and fruit-eaters move them.", "A new patch of soil is a new chance.", "That is why dandelions have parachutes."),
    ("Why Is Soil Important?", "rock", "#8D6E63", "Soil is not just dirt.", "It holds water, air, and tiny helpers.", "Roots drink from it. Worms mix it.", "Healthy soil grows healthy food."),
    ("Why Do We Recycle?", "earth", "#66BB6A", "Recycling gives used stuff a second job.", "Less new mining. Less trash in the ground.", "Sort paper, plastic, metal, and glass.", "Your bin choice is a real planet choice."),
    ("Why Does a Compass Point North?", "earth", "#5C6BC0", "Earth has a magnetic field, like a giant quiet magnet.", "A compass needle lines up with that field.", "The painted end seeks magnetic north.", "Explorers used this before GPS."),
    ("Why Do Clocks Have Hands?", "clock", "#90CAF9", "A clock splits a day into hours and minutes.", "The short hand is hours. The long hand is minutes.", "A circle of 12 repeats twice a day.", "Reading a clock is reading time's map."),
    ("Why Do We Have Time Zones?", "earth", "#42A5F5", "Noon is when the sun is highest where you are.", "Earth is round, so noon cannot be everywhere at once.", "Time zones keep local noon near 12.", "Call a far friend and their clock may disagree."),
    ("Why Do Planes Fly?", "rocket", "#90CAF9", "Air moving over a wing is shaped to lift.", "Engines push the plane forward so air keeps flowing.", "Lift beats weight. Thrust beats drag.", "That balance is flight."),
    ("Why Do Rockets Need Fuel?", "rocket", "#FF7043", "A rocket carries its own push.", "Burning fuel blasts gas backward.", "The rocket goes forward. That is action and reaction.", "No air in space, so the blast still works."),
    ("Why Is Mars Red?", "earth", "#E57373", "Mars dust has rusted iron in it.", "Rusty dust covers rocks and sky tints.", "That is why it looks rusty red.", "A whole planet wearing iron rust."),
    ("Why Do We Have Day and Night?", "sun", "#FFD54F", "Earth spins like a slow top.", "Your side faces the sun: day.", "Your side turns away: night.", "One full spin is about 24 hours."),
    ("Why Can't We Live on the Moon?", "moon", "#B0BEC5", "The moon has almost no air to breathe.", "Days are scorching. Nights are freezing.", "No liquid water on the surface.", "Astronauts bring air, water, and suits."),
    ("Why Do We Need Bones?", "bone", "#FFF8E1", "Bones are your inner scaffolding.", "They protect the brain and heart.", "Muscles pull on bones so you can move.", "Milk, greens, and play help bones grow strong."),
    ("Why Do We Need Muscles?", "hand", "#FFAB91", "Muscles are pullers, not pushers.", "They shorten to lift, kick, and smile.", "Use them and they get stronger.", "Rest them and they recover."),
    ("Why Does Exercise Help?", "heart", "#EF9A9A", "Moving makes the heart pump harder in a good way.", "Muscles get more oxygen.", "Your mood chemicals get a lift too.", "Play counts as exercise."),
    ("Why Do We Need Water?", "water", "#29B6F6", "Your body is mostly water.", "Water carries stuff in blood and sweat.", "It helps cool you and keeps cells working.", "Thirst is a helpful alarm. Drink up."),
    ("Why Do We Need Food?", "apple", "#FF7043", "Food is fuel and building blocks.", "Carbs and fats give energy.", "Protein helps build muscle and more.", "A mix of foods covers the jobs."),
    ("Why Do We Have Blood?", "heart", "#E57373", "Blood is a delivery river.", "It carries oxygen, food, and messages.", "It also hauls away waste.", "Kid-safe fact: it is a transport system, not a scare."),
    ("Why Does the Heart Beat?", "heart", "#E91E63", "The heart is a muscle pump.", "It squeezes to push blood out.", "It relaxes to fill again.", "That lub-dub is one pump cycle."),
    ("Why Do Lungs Matter?", "heart", "#81D4FA", "Lungs take in oxygen and send out carbon dioxide.", "Air tubes branch like a tree inside.", "The tiny ends swap gases with blood.", "Breathing is that swap, all day."),
    ("Why Do We Get Fevers?", "heart", "#FF8A65", "A fever is your body turning the heat up.", "Some germs hate extra heat.", "Rest and water help you through it.", "A grown-up should check a high fever."),
    ("Why Do Vaccines Help?", "heart", "#80CBC4", "A vaccine is a practice round for your immune team.", "It teaches your body a germ's face safely.", "Later, the real germ is easier to stop.", "That is training, not a trick."),
    ("Why Do We Have Skin?", "hand", "#FFCCBC", "Skin is a living wrap.", "It keeps water in and many germs out.", "It feels heat, cold, and touch.", "Sunscreen helps on bright days."),
    ("Why Do We Have Hair?", "animal", "#A1887F", "Hair can warm the head and keep dust out of eyes.", "Eyebrows are rain guards for your eyes.", "Hair is made of a tough protein.", "It is dead at the tips, alive at the root."),
    ("Why Do Nails Grow?", "hand", "#FFCC80", "Nails protect the ends of fingers and toes.", "They grow from a root under the skin.", "The white tip is already finished keratin.", "Trim them. Do not bite them."),
    ("Why Do We Taste Sweet?", "apple", "#F8BBD0", "Sweet often meant ripe fruit and energy.", "Your tongue has taste partners for sweet, salty, sour, bitter, and savory.", "Brain plus nose makes flavor.", "That is why a cold can make food dull."),
    ("Why Do We Smell Smoke?", "fire", "#FF7043", "Smell is an early warning system.", "Smoke means fire might be near.", "Your nose sends a fast message: check and get safe.", "If you smell smoke, tell a grown-up."),
    ("Why Does Sound Get Quieter Far Away?", "ear", "#B0BEC5", "A sound wave spreads out like a ripple.", "The same energy covers more space.", "Farther away, each bit of air shakes less.", "That is why a shout fades."),
    ("Why Does a Straw Work?", "water", "#4FC3F7", "You do not really suck the drink up by magic.", "You lower the air pressure in the straw.", "Outside air then pushes the drink up.", "Air pressure is the hidden helper."),
    ("Why Does Popcorn Pop?", "apple", "#FFE082", "A kernel hides a drop of water inside a hard shell.", "Heat turns that water into steam.", "Steam wants space. The shell bursts.", "The white puff is the inside turning inside-out."),
    ("Why Does Rubber Stretch?", "shape", "#FF8A65", "Rubber's long molecules are coiled like springs.", "Pull, and they uncoil.", "Let go, and they curl back.", "That springiness is elasticity."),
    ("Why Does Glass Break?", "shape", "#90CAF9", "Glass is hard but not bendy.", "A sharp hit makes a crack race through.", "Once the crack starts, it can zip.", "Handle glass with two hands."),
    ("Why Does Wood Float and Rock Sink?", "wave", "#8D6E63", "Density is mass packed into a space.", "Wood packs loosely compared with water, so it floats.", "Most rocks pack tighter, so they sink.", "A huge wooden ship still floats if it is shaped right."),
    ("Why Do We Oil Bike Chains?", "car", "#78909C", "Metal on metal grinds and heats.", "Oil makes a slippery film.", "Parts slide instead of scrape.", "Less scrape means a longer-lasting chain."),
    ("Why Do Tires Have Tread?", "car", "#546E7A", "Smooth rubber hydroplanes on wet roads.", "Tread channels water away.", "Then rubber can grip the ground.", "Bald tires are unsafe in rain."),
    ("Why Do Bridges Have Triangles?", "shape", "#90A4AE", "A triangle is a stiff shape.", "Push one corner and the sides share the load.", "Truss bridges are triangle teams.", "Geometry keeps the span from sagging."),
    ("Why Do Windows Fog?", "cloud", "#B3E5FC", "Warm wet air hits cold glass.", "Water vapor turns back into tiny drops.", "Those drops make fog on the pane.", "That change is condensation."),
    ("Why Does Salt Melt Ice?", "ice", "#ECEFF1", "Salt makes it harder for water to stay frozen.", "The freezing point drops.", "Ice starts to melt at a colder temperature.", "That is why trucks salt winter roads."),
    ("Why Do We See Our Breath in Winter?", "cloud", "#90CAF9", "Your breath is warm and wet.", "Cold air cools it fast.", "The water becomes a little cloud.", "Summer air is already warm, so no cloud."),
    ("Why Is Snow White?", "snow", "#E3F2FD", "A snowflake is clear ice.", "Many flakes bounce light in all directions.", "All colors bounce, so we see white.", "Piled ice can look white like crushed glass."),
    ("Why Do Clouds Stay Up?", "cloud", "#ECEFF1", "Cloud drops are tiny, like dust.", "Air moving up can hold them.", "When drops grow heavy, they fall as rain.", "A cloud is a floating crowd of droplets."),
    ("Why Is a Desert Dry?", "rock", "#FFCC80", "Some deserts sit where winds drop their rain earlier.", "Mountains can block wet air too.", "Less rain means fewer plants.", "Deserts can still be full of life, just thirsty-smart life."),
    ("Why Do Mountains Form?", "rock", "#8D6E63", "Earth's crust is cracked into slow-moving plates.", "When plates push, rock crumples upward.", "That crumple can become a mountain range.", "It takes millions of years, not a weekend."),
    ("Why Do Volcanoes Erupt?", "fire", "#FF5722", "Melted rock under the crust wants a way out.", "Pressure builds. Then it finds a weak spot.", "Lava, ash, and gas can come out.", "We watch from a safe distance. Never visit an active vent."),
    ("Why Do Earthquakes Happen?", "rock", "#6D4C41", "Stuck plates suddenly slip.", "The slip shakes the ground.", "That shake is an earthquake.", "Drop, cover, and hold on if you feel one."),
    ("Why Is the Equator Hot?", "sun", "#FFB74D", "Sunlight hits the equator more straight-on.", "The same energy is spread less.", "Poles get sunlight at a slant, so it is weaker.", "That is why tropics stay warm."),
    ("Why Do Maps Lie a Little?", "earth", "#42A5F5", "Earth is a ball. A paper map is flat.", "Flattening a ball stretches some countries.", "Greenland looks huge on some maps. It is not that huge.", "Globes keep the true sizes."),
    ("Why Do We Have Gravity?", "apple", "#E53935", "Mass pulls on mass.", "Earth is huge, so it pulls you down.", "Jump, and gravity calls you back.", "The moon has gravity too, just weaker."),
    ("Why Does a Ball Come Down?", "ball", "#EF5350", "Throw a ball up and gravity wins.", "Air also slows it a bit.", "At the top, speed is zero for a blink.", "Then down it comes."),
    ("Why Do Helicopters Hover?", "rocket", "#78909C", "Spinning blades push air down.", "The air pushes the helicopter up.", "Balance that push with weight and it hovers.", "Pilots adjust the blades many times a second."),
    ("Why Do Submarines Dive?", "wave", "#1565C0", "Tanks fill with water to get heavier.", "Heavier than the water it pushes aside, it sinks.", "Pump water out, it rises.", "That is buoyancy control."),
    ("Why Is Night Sky Black?", "star", "#1A237E", "Space between stars is mostly empty.", "Empty does not glow.", "Air on Earth also blocks some starlight.", "City lights make the black look gray. That is light pollution."),
    ("Why Do We Need Darkness to See Stars?", "star", "#3949AB", "Stars are there in the day too.", "The blue sky is so bright it hides them.", "Night turns down the sky's glare.", "Then faint stars can win."),
    ("Why Does the Sun Rise in the East?", "sun", "#FFA726", "Earth spins toward the east.", "So the sun appears to climb from that side.", "It is Earth moving, not the sun racing around us.", "Sunset is the same spin, other side."),
    ("Why Do We Have Leap Years?", "clock", "#7E57C2", "Earth's trip around the sun is not a perfect 365 days.", "It is about a quarter-day extra.", "Every four years we add February 29.", "That extra day keeps calendars honest."),
    ("Why Do Calendars Have Months?", "moon", "#7986CB", "Months began as moon cycles.", "A moon cycle is about 29 and a half days.", "Twelve of those nearly fill a year.", "Names like month and moon are cousins."),
    ("Why Do We Use Money?", "book", "#FFD54F", "Money is a shared IOU everyone agrees on.", "It is easier than trading a chicken for shoes.", "Coins and bills stand for value.", "Saving is parking some value for later."),
    ("Why Do Libraries Exist?", "book", "#8D6E63", "A library lets many people share books.", "You borrow. You return. Someone else learns.", "Knowledge is a team sport.", "A library card is a ticket to more brains than one house can hold."),
    ("Why Do We Write?", "book", "#5D4037", "Talking disappears when the sound dies.", "Writing holds words still.", "That is how we send ideas across time.", "Your homework is practice for that superpower."),
    ("Why Do Languages Differ?", "ear", "#26A69A", "People far apart invented different word-systems.", "Each language is a toolkit for thinking.", "Learning one more toolkit grows your world.", "Malayalam, English, and thousands more are all human."),
    ("Why Do We Have Names?", "heart", "#F48FB1", "A name is a handle for a person.", "It helps us call, remember, and respect.", "You can have a home name and a school name.", "Your name is part of your story."),
    ("Why Do We Celebrate Birthdays?", "heart", "#FF8A65", "A birthday marks one more trip around the sun.", "We pause to say you matter.", "Cake is optional. Kindness is not.", "Another year of you is worth noticing."),
    ("Why Do Team Sports Help?", "ball", "#43A047", "A team shares a goal.", "You practice passing, not just scoring.", "Losing can teach grit if the adults stay kind.", "Play hard. Shake hands."),
    ("Why Do Rules Exist in Games?", "shape", "#7E57C2", "Rules make a game fair and possible.", "Without them, nobody knows how to win.", "Good rules protect players too.", "If a rule is unkind, grown-ups can change it."),
    ("Why Do We Feel Nervous?", "heart", "#9575CD", "Nerves are your body getting ready.", "Heart faster. Muscles alert.", "A little nervous can help you try.", "Breathe slow if it gets too big. Tell someone."),
    ("Why Do We Feel Angry?", "heart", "#EF5350", "Anger says something feels unfair or stuck.", "The feeling is allowed. Hurting is not.", "Name it. Pause. Then choose a safe action.", "That is strength, not stuffing it down."),
    ("Why Do We Feel Sad?", "heart", "#7986CB", "Sadness is for loss and letdowns.", "Tears can help your body reset.", "Talking to a trusted person helps more than hiding.", "Sad is not forever, even when it feels huge."),
    ("Why Do Friends Matter?", "heart", "#F06292", "Friends make hard days lighter.", "They practice kindness with you.", "A good friend listens and tells the truth kindly.", "Be that friend back."),
    ("Why Should We Tell the Truth?", "book", "#8D6E63", "Truth lets people trust you.", "Lies pile up and get heavy.", "Honest mistakes can be fixed.", "Trust is slow to build and fast to crack."),
    ("Why Is Sharing Hard and Helpful?", "apple", "#AED581", "Your brain likes keeping the good stuff.", "Sharing builds a team around you.", "You still can have boundaries.", "Kind and clear can live together."),
    ("Why Do We Go to School?", "book", "#5C6BC0", "School is a gym for your mind.", "You practice reading, numbers, and getting along.", "Teachers hand you tools faster than guessing alone.", "The real prize is becoming a person who can learn anything."),
    ("Why Do Scientists Do Experiments?", "circuit", "#FFC107", "A guess is not enough.", "An experiment asks nature the same question, carefully.", "If the answer repeats, the idea gets stronger.", "If not, scientists change the idea. That is courage."),
    ("Why Do Inventions Happen?", "circuit", "#FFA726", "Someone notices a bother and designs a helper.", "Wheel, writing, vaccine, light bulb.", "Failures teach the next try.", "You can invent too, even a better backpack hook."),
    ("Why Do Computers Use Ones and Zeros?", "circuit", "#26C6DA", "A tiny switch is easy to make on or off.", "On can mean one. Off can mean zero.", "Billions of those switches make pictures and games.", "That is the quiet language of chips."),
    ("Why Does a Light Switch Work?", "circuit", "#FFEE58", "A switch opens or closes a loop.", "Closed loop: electricity can flow. Light on.", "Open loop: the path breaks. Light off.", "You are the gatekeeper of that tiny racetrack."),
    ("Why Do Batteries Die?", "circuit", "#8BC34A", "A battery stores a chemical push.", "Using it spends that stored change.", "When the chemicals are used up, the push fades.", "Rechargeables can run the reaction backward."),
    ("Why Is Plastic Everywhere?", "earth", "#29B6F6", "Plastic is light, cheap, and waterproof.", "Those strengths became a trash problem.", "It lasts a long time in nature.", "Reuse, refuse extras, and recycle when you can."),
    ("Why Do We Need Bees?", "bee", "#FBC02D", "Bees move pollen from flower to flower.", "No pollen trip, fewer fruits and veggies.", "Honey is a bonus. Pollination is the main job.", "Plant flowers. Skip extra pesticides when you can."),
    ("Why Do Coral Reefs Matter?", "wave", "#26A69A", "Reefs are ocean apartment buildings.", "Fish hide, eat, and grow there.", "Warming seas can bleach coral.", "Protecting reefs protects a huge web of life."),
    ("Why Do Polar Bears Have White Fur?", "snow", "#ECEFF1", "The fur looks white and blends with snow.", "Underneath, skin is dark to hold heat.", "Hollow hairs can trap warmth.", "Camouflage plus insulation is Arctic design."),
    ("Why Do Chameleons Change Color?", "animal", "#9CCC65", "Color shifts can mean mood, heat, or messages.", "It is not only hiding.", "Tiny skin crystals and pigments do the trick.", "A walking mood ring, with a long tongue."),
    ("Why Do Dogs Wag?", "animal", "#A1887F", "A wag can mean hello, let's play, or I am unsure.", "Watch the whole dog, not just the tail.", "A loose wiggly body is usually friendly.", "Ask before you pet."),
    ("Why Do Cats Land on Their Feet?", "cat", "#FFB74D", "A cat can twist in the air using its spine and tail.", "Eyes and inner ears tell it which way is down.", "They still can get hurt from high places.", "Keep windows safe."),
    ("Why Do Horses Sleep Standing?", "animal", "#8D6E63", "Special leg locks let a horse rest without falling.", "They still lie down for deeper sleep.", "In the wild, standing helped them flee fast.", "Farm horses keep the habit."),
    ("Why Do Cows Chew Twice?", "animal", "#E0E0E0", "Grass is tough.", "A cow swallows, then brings it back to chew again.", "That extra chew helps bacteria break it down.", "The second chew is called chewing the cud."),
    ("Why Do Ducks Have Webbed Feet?", "animal", "#FDD835", "Webs turn feet into paddles.", "Push water. Glide.", "On land they waddle because of that same shape.", "Right tool for the pond."),
    ("Why Do Flamingos Stand on One Leg?", "bird", "#F48FB1", "Tucking one leg can save heat.", "The stance is also surprisingly stable.", "Scientists still argue about every reason.", "Science can say we are not sure yet. That is honest."),
    ("Why Do Woodpeckers Not Get Headaches?", "bird", "#E53935", "A woodpecker skull is built to spread the shock.", "Tiny air spaces and strong neck muscles help.", "The brain is packed snugly.", "Do not copy this with your own head."),
    ("Why Do Snakes Stick Out Their Tongues?", "animal", "#8BC34A", "The tongue samples the air.", "Smell particles stick, then go to a special organ.", "Two tongue tips can tell left from right scent.", "It is smelling, not being rude."),
    ("Why Do Crabs Walk Sideways?", "animal", "#EF9A9A", "Crab joints bend easily to the side.", "Sideways steps fit their wide bodies.", "Some crabs can walk forward too.", "Beach engineering, not a dance trend."),
    ("Why Do Octopuses Have Three Hearts?", "wave", "#7E57C2", "Two hearts push blood to the gills.", "One heart pushes blood to the body.", "When it swims, that body heart can pause.", "Ocean animals solve problems in wild ways."),
    ("Why Is Blood Blue in Veins?", "heart", "#90CAF9", "Your blood is never really blue.", "Veins look blue because of how light travels through skin.", "Oxygen-rich blood is bright red.", "Textbook diagrams sometimes trick people."),
    ("Why Do We Get Brain Freeze?", "ice", "#B3E5FC", "Cold hits a nerve in the roof of your mouth.", "The brain reads it as head pain.", "It fades fast when you warm the spot.", "Press your tongue up. Slow down on the ice cream."),
    ("Why Do We Get Side Stitches?", "heart", "#FFAB91", "A stitch is a cramp in your side when you run.", "Breathing and a full stomach can play a part.", "Slow down. Raise the arm on that side. Breathe."),
    ("Why Do We Get Charley Horses?", "hand", "#BCAAA4", "A charley horse is a sudden muscle cramp.", "Tired muscles and low fluids can trigger it.", "Gently stretch. Drink water.", "Tell a grown-up if cramps keep coming."),
    ("Why Do We Get Paper Cuts?", "hand", "#FFF8E1", "Paper edges are thinner than they look.", "They slice skin just enough to hurt a lot.", "Fingers have many nerves.", "Wash. Bandage. The sting means those nerves work."),
    ("Why Do Bandages Help?", "heart", "#EF9A9A", "A clean cover keeps dirt out.", "It also reminds you not to pick.", "The body still does the real healing.", "Change it if it gets wet or dirty."),
    ("Why Do Scabs Form?", "heart", "#FFCCBC", "A scab is a natural bandage of dried blood proteins.", "It keeps the door closed while new skin grows.", "Picking it reopens the door.", "Let it fall off when it is ready."),
    ("Why Do We Need Vitamin D?", "sun", "#FFD54F", "Sun on skin helps your body make vitamin D.", "That vitamin helps bones use calcium.", "Foods and drops can help too.", "A little sun. Not a burn."),
    ("Why Do We Wear Sunscreen?", "sun", "#FFB74D", "Sunlight has ultraviolet rays.", "Too much can burn and age skin.", "Sunscreen is a shield you rub on.", "Reapply after swimming."),
    ("Why Do We Wear Helmets?", "shape", "#5C6BC0", "A helmet spreads a hit so your skull takes less of it.", "Foam crushes on purpose to save your brain.", "One crash can be one too many.", "Chin strap on. Every ride."),
    ("Why Do Seat Belts Matter?", "car", "#546E7A", "A crash stops the car. You keep moving unless something holds you.", "The belt is that something.", "It spreads the force across strong bones.", "Click. Every trip. Every seat."),
    ("Why Do Smoke Alarms Beep?", "fire", "#FF7043", "They sniff the air for smoke particles.", "A loud beep buys you time to get out.", "Test them. Change batteries with a grown-up.", "Two beeps at night? Get out. Do not hide."),
    ("Why Do We Cross at Crosswalks?", "car", "#42A5F5", "Drivers expect people there.", "Paint and lights are a shared plan.", "Look left, right, left.", "The shortest path is not always the safest path."),
    ("Why Do Life Jackets Float You?", "wave", "#0288D1", "Foam traps air.", "Air is less dense than water, so it lifts.", "The jacket keeps your face up if you cannot swim well.", "Wear it before you need it."),
    ("Why Do We Need Fire Drills?", "fire", "#FF8A65", "Practice makes the scary path familiar.", "Your feet learn the way when your brain is busy.", "Walk. Do not push.", "A drill is a rehearsal for staying alive."),
    ("Why Do 999 and 112 Exist?", "heart", "#E53935", "Emergency numbers skip the wait.", "Trained people send help fast.", "Use them for real danger, not jokes.", "Know your address. Stay on the line."),
    ("Why Do Passwords Matter?", "circuit", "#7E57C2", "A password is a key to your digital stuff.", "A guessable key is a gift to strangers.", "Long and unique is stronger than clever.", "Do not share it, even with a friend who asks nicely."),
    ("Why Should We Not Share Photos of Other Kids?", "heart", "#F48FB1", "A photo is someone's face and a moment they own.", "Online, it can travel farther than you meant.", "Ask first. A grown-up should help.", "Kindness includes privacy."),
    ("Why Do Rumors Spread?", "ear", "#B39DDB", "A surprising story wants to be retold.", "Truth is slower than a juicy guess.", "Pause. Ask, is this kind and true?", "Not passing it on is a superpower."),
    ("Why Do Ads Want Your Attention?", "book", "#FFA726", "Attention can be sold.", "Ads are designed to tug eyes and feelings.", "You can notice the tug and keep walking.", "You are more than a customer."),
    ("Why Is Boredom Useful?", "moon", "#90A4AE", "A bored brain starts inventing.", "No screen for a bit and ideas wander in.", "Boredom is empty space for making.", "Sit with it. Then build something."),
    ("Why Do We Dream?", "moon", "#5C6BC0", "Sleeping brains still work.", "Dreams may file memories and feelings.", "Some dreams are weird leftovers of the day.", "A nightmare is not a prophecy. Tell someone if it sticks."),
    ("Why Do We Laugh?", "heart", "#FFD54F", "Laughing is a social glue sound.", "It can mean play, relief, or surprise.", "Your body relaxes a little.", "Kind laughter includes people. Mean laughter shuts them out."),
    ("Why Do We Cry Happy Tears?", "heart", "#81D4FA", "Feelings can overflow in more than one direction.", "Tears are a body valve.", "Happy, sad, or spicy onions can all open it.", "Your face is allowed to be complicated."),
    ("Why Do Hugs Help?", "heart", "#F48FB1", "A gentle hug can slow a racing heart.", "Warm pressure says you are not alone.", "Ask first. Not everyone wants a hug.", "A wave or kind words can be a hug too."),
    ("Why Do Pets Help Some People?", "cat", "#A1887F", "A calm animal can lower stress.", "Caring for a pet is practice for caring.", "Pets still need food, vet visits, and patience.", "A stuffed animal can help too if a live pet is not possible."),
    ("Why Do Plants Bend Toward Light?", "seed", "#81C784", "Light is food-making energy for plants.", "A plant hormone shifts so the stem leans to the bright side.", "That lean is phototropism.", "Put a bean in a window and watch it cheat toward the sun."),
    ("Why Do Roots Grow Down?", "seed", "#8D6E63", "Roots follow gravity and moisture.", "Down is usually where water and grip are.", "That down-sense is gravitropism.", "Flip a seedling and the root will try to turn."),
    ("Why Do Mushrooms Appear After Rain?", "seed", "#BCAAA4", "The fungus was already in the soil.", "Rain helps the fruiting part pop up.", "The mushroom is like an apple. The tree is underground.", "Never eat a wild one. Many look friendly and are not."),
    ("Why Do Fireflies Glow?", "star", "#F9A825", "A chemical reaction in the belly makes cold light.", "The flashes are messages to other fireflies.", "Different patterns mean different species.", "Catch, look, let go."),
    ("Why Do Crickets Chirp?", "ant", "#8D6E63", "A cricket rubs wings like a tiny violin.", "Mostly males call to be found.", "Faster chirps can mean warmer air.", "Night soundtrack, insect style."),
    ("Why Do Mosquitoes Buzz?", "ant", "#78909C", "Fast wingbeats make the whine.", "Some mosquitoes look for a blood meal to make eggs.", "You are not their only option. Still, screens help.", "Slap is allowed. Do not share that part with toddlers as a game."),
    ("Why Do Ticks Matter?", "ant", "#6D4C41", "Ticks can carry germs.", "Check after woods and tall grass.", "A grown-up should remove one the safe way.", "Long sleeves and a look-over beat panic."),
    ("Why Do We Compost?", "seed", "#7CB342", "Peels and leaves can become soil food.", "Tiny life eats them and leaves nutrients.", "That is recycling for the garden.", "No meat in many home bins. Follow your local rules."),
    ("Why Do Wind Turbines Spin?", "wind", "#90CAF9", "Moving air pushes angled blades.", "The spin turns a generator.", "Motion becomes electricity.", "Wind is a power plant with no smoke."),
    ("Why Do Solar Panels Work?", "sun", "#FFD54F", "Sunlight knocks electrons in special silicon.", "Those electrons are pushed into a circuit.", "Daylight becomes electric current.", "Clouds weaken it. Night pauses it."),
    ("Why Do Dams Make Electricity?", "water", "#0277BD", "High water has stored energy.", "Let it fall through turbines and they spin.", "That spin makes electricity.", "The tradeoff is changing a river. Engineers debate it."),
    ("Why Do We Need Power Grids?", "circuit", "#FFC107", "A grid is a sharing network for electricity.", "Power plants, wires, homes.", "If one part fails, others can sometimes cover.", "Flip a switch and you tap a continent-sized machine."),
    ("Why Do Outages Happen?", "circuit", "#546E7A", "Storms, heat, or a broken line can stop the flow.", "The grid protects itself by shutting pieces off.", "Flashlights beat candles for kids.", "Unplug fancy gear until power is steady."),
    ("Why Is Water a Good Coolant?", "water", "#4FC3F7", "Water can take in a lot of heat before it gets much hotter.", "That is a high specific heat.", "Engines and power plants use that trick.", "Your sweat uses it too."),
    ("Why Does Metal Expand When Hot?", "rock", "#90A4AE", "Heat makes atoms jiggle more.", "They take more space. The metal grows a tiny bit.", "Bridges have gaps for this.", "Without gaps, a hot day could buckle the road."),
    ("Why Do Train Tracks Click?", "car", "#78909C", "Rails are in sections or still flex.", "Wheels hit joints. Clickety-clack.", "Heat can change the gaps.", "The rhythm is engineering, not a drummer under the train."),
    ("Why Do Skyscrapers Sway?", "shape", "#90A4AE", "Wind pushes tall buildings.", "A little sway is safer than being perfectly stiff.", "Massive dampers can calm the dance.", "If you feel a gentle sway, that can be by design."),
    ("Why Do Elevators Have Cables and Brakes?", "shape", "#546E7A", "Cables lift. Brakes wait for trouble.", "Safety gears can grab the rails if speed is wrong.", "A counterweight saves energy.", "Elevator fear is common. The machines are overbuilt on purpose."),
    ("Why Do Airports Have Long Runways?", "rocket", "#90CAF9", "A plane needs time to reach flying speed.", "Heavy plane plus little wind means more asphalt.", "Landing needs room to slow too.", "That ribbon of pavement is a speed ramp."),
    ("Why Do Ships Use Containers?", "wave", "#1565C0", "Same-size boxes stack like bricks.", "Cranes move them fast.", "One box, many products, worldwide.", "The quiet revolution that filled stores."),
    ("Why Do Barcodes Exist?", "book", "#455A64", "A barcode is a price-tag the computer can see.", "Stripes encode numbers.", "A laser or camera reads them in a blink.", "Checkout is a tiny library scan."),
    ("Why Do QR Codes Hold More?", "circuit", "#212121", "A QR code is a 2D barcode.", "It stores more than stripes can.", "Phones read the pattern as a link or text.", "Ask a grown-up before scanning a random one."),
    ("Why Do Photos Need Light?", "sun", "#FFE082", "A camera is a light catcher.", "Too little light, a dark smudge.", "Lenses bend light onto a sensor.", "You are painting with photons."),
    ("Why Do Movies Need Many Pictures?", "shape", "#5C6BC0", "A movie is still pictures in a hurry.", "Your brain blends them into motion.", "That blend is persistence of vision, plus brain guesswork.", "Twenty-four frames a second is a common film pace."),
    ("Why Does Color TV Work?", "rainbow", "#EC407A", "Red, green, and blue dots mix.", "Your eyes add them into other colors.", "That is the same trick as many screens.", "White is all three shouting together."),
    ("Why Do Headphones Work?", "ear", "#424242", "A tiny speaker shakes air next to your ear.", "Those shakes are the song.", "Volume too high can harm hearing forever.", "If someone else can hear your song, it is too loud."),
    ("Why Does a Guitar Make Notes?", "ear", "#8D6E63", "A string's length, tightness, and thickness set its pitch.", "Shorter or tighter is higher.", "The body of the guitar amplifies the air shake.", "Your fingers are changing math in real time."),
    ("Why Does a Drum Boom?", "ear", "#6D4C41", "A stretched skin is a springy membrane.", "Hit it, and it wobbles air.", "A bigger drum wobbles slower. Lower boom.", "Rhythm is patterned time."),
    ("Why Can Music Change Mood?", "heart", "#7E57C2", "Beats can nudge heart rate and attention.", "Melody and memory get tangled.", "A sad song can help a sad day feel seen.", "You get to pick the soundtrack. Choose kind."),
    ("Why Do We Have Two Eyes?", "eye", "#90CAF9", "Two eyes sit a little apart.", "Each sees a slightly different picture.", "Your brain stacks them into depth.", "That is why a ball coming at you is easier to catch."),
    ("Why Do We Have Two Ears?", "ear", "#FFCCBC", "A sound hits one ear a tiny bit first.", "Louder in the nearer ear too.", "Your brain uses that gap to find the direction.", "Cover one ear and the world feels flatter."),
    ("Why Do Balls Bounce?", "ball", "#EF5350", "A bounce is a stored squish coming back.", "The ball flattens, then springs toward round.", "Some energy is lost as heat and sound.", "A dead ball has lost that spring."),
    ("Why Do We See Reflections?", "water", "#4FC3F7", "Smooth stuff can bounce light like a trampoline.", "A mirror is glass with a shiny metal back.", "Still water can act like a weak mirror.", "Ripples scramble the bounce, so the face breaks up."),
    ("Why Does a Fan Cool You?", "wind", "#90CAF9", "A fan does not make cold air from nowhere.", "It blows your warm air and sweat away.", "Sweat drying steals heat from skin.", "That is why a fan feels weak in very humid air."),
    ("Why Do We Get Dizzy After Spinning?", "star", "#FFE082", "Fluid in your inner ear keeps spinning a moment.", "Your eyes say you stopped. Your ears say you did not.", "That argument is dizziness.", "Sit. Focus on one still thing. It passes."),
    ("Why Do We Have Fingerprints?", "hand", "#FFCC80", "Tiny ridges help you grip smooth things.", "They also make each fingertip a unique stamp.", "Even identical twins differ a bit.", "They are tools first, detective clues second."),
    ("Why Does Bread Get Stale?", "apple", "#D7CCC8", "Fresh bread holds water in a soft web of starch.", "That water slowly leaves or rearranges.", "The slice goes firm. That is stale, not always moldy.", "A short toast can wake some softness back."),
    ("Why Do Leaves Have Veins?", "leaf", "#66BB6A", "Veins are the leaf's pipes.", "They carry water in and sugar out.", "The pattern also keeps the leaf from tearing easily.", "A leaf is a solar panel with plumbing."),
    ("Why Does a Seesaw Work?", "shape", "#FFA726", "A seesaw is a lever with a middle fulcrum.", "A heavier friend sits closer to the middle to balance.", "Distance times weight is the trade.", "Playground physics you can feel."),
    ("Why Do We Get Static Shocks in Winter?", "bubble", "#B39DDB", "Dry winter air lets extra charge sit on you.", "A doorknob lets it jump at once.", "That snap is a tiny lightning bolt, not a monster.", "Touch metal with a key to spill the charge slower."),
    ("Why Does Honey Last So Long?", "bee", "#FBC02D", "Honey is very low in water and quite acidic.", "Many germs cannot grow in that desert of sugar.", "Sealed well, it can stay safe for years.", "If it crystals, warm the jar gently. Do not feed honey to babies."),
    ("Why Do We Get Cavities?", "tooth", "#FFF8E1", "Mouth bacteria eat leftover sugar.", "They make acid that can nibble enamel.", "Brushing and flossing break up that film.", "A dentist catch early beats a big ache later."),
    ("Why Does the Fridge Hum?", "ice", "#90CAF9", "A fridge pumps heat out of the box.", "The motor and fan make that familiar hum.", "If it never hums, food may not stay cold.", "Keep the door shut. Cold air is expensive to remake."),
    ("Why Do Birds Have Hollow Bones?", "bird", "#26A69A", "Many bird bones are light with inner struts.", "Less weight makes flight cheaper in energy.", "They are still strong, like a bicycle frame.", "Not empty like a straw. Engineered empty."),
    ("Why Do We Get Sleepy After Lunch?", "moon", "#7986CB", "A full stomach sends extra blood toward digestion.", "A heavy meal can nudge a natural afternoon dip.", "Protein plus a walk beats a sugar crash.", "A short rest can help. A long nap can steal night sleep."),
    ("Why Does Aluminum Foil Shine?", "rock", "#B0BEC5", "Foil is metal rolled almost paper-thin.", "Smooth metal bounces a lot of light.", "That bounce looks like shine.", "The duller side is just a little rougher from the mill."),
    ("Why Do We Need Eyebrows?", "eye", "#A1887F", "Eyebrows are rain and sweat guards.", "They also flash feelings across a room.", "Raise them. We read surprise without a word.", "A tiny roof for your eyes, plus a signal flag."),
    ("Why Does a Slide Feel Fast?", "shape", "#42A5F5", "Gravity pulls you down the slope.", "Smooth plastic has little friction.", "You convert height into speed.", "Feet first. One at a time. That keeps the fun safe."),
]


def pack_kids() -> list[dict]:
    out = []
    for row in KIDS:
        title, scene, accent, *lines = row
        out.append(
            {
                "title": title,
                "scene": scene,
                "accent": accent,
                "hook": lines[0],
                "narration": list(lines),
            }
        )
    return out
